CREATE OR REPLACE FUNCTION private.assert_outbox_payload_refs_safe_v1(p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare k text;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'outbox payload_refs must be a JSON object';
  end if;
  for k in select jsonb_object_keys(p_payload)
  loop
    if lower(k) ~ '(body|text|content|message|email|phone|name|address|title|question|answer|statement|quote|prompt)' then
      raise exception 'outbox payload_refs key "%" may contain content/PII; only identifiers, versions, hashes and flags are allowed', k;
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.mirror_native_qna_to_legacy_v1(p_company_id uuid, p_question_id uuid, p_question text, p_answer text, p_category text, p_program_label text, p_publish boolean, p_user_id uuid, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_legacy uuid; v_now timestamptz:=now();
begin
 select legacy_qna_id into v_legacy from private.questions_v1 where id=p_question_id and company_id=p_company_id for update;
 perform set_config('otzovik.native_mirror','on',true);
 if v_legacy is null then
   insert into public.company_questions_answers(company_id,question,answer,category,program_label,source_system,provenance,status,answered_at,published_at)
   values(p_company_id,btrim(p_question),btrim(p_answer),nullif(btrim(p_category),''),nullif(btrim(p_program_label),''),'otzovik',jsonb_build_object('source','phase9b_native_mirror','actor_user_id',p_user_id,'actor_role',p_role),case when p_publish then 'published' else 'draft' end,v_now,case when p_publish then v_now else null end) returning id into v_legacy;
   update private.questions_v1 set legacy_qna_id=v_legacy where id=p_question_id and company_id=p_company_id;
 else
   update public.company_questions_answers set question=btrim(p_question),answer=btrim(p_answer),category=nullif(btrim(p_category),''),program_label=nullif(btrim(p_program_label),''),status=case when p_publish then 'published' else 'draft' end,answered_at=v_now,published_at=case when p_publish then coalesce(published_at,v_now) else null end,updated_at=v_now,provenance=coalesce(provenance,'{}'::jsonb)||jsonb_build_object('source','phase9b_native_mirror','last_actor_user_id',p_user_id,'last_actor_role',p_role) where id=v_legacy and company_id=p_company_id;
 end if;
 perform set_config('otzovik.native_mirror','off',true);
 return v_legacy;
exception when others then perform set_config('otzovik.native_mirror','off',true); raise;
end $function$

CREATE OR REPLACE FUNCTION private.mirror_native_review_response_to_legacy_v1(p_company_id uuid, p_review_id uuid, p_statement text, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
 perform set_config('otzovik.native_mirror','on',true);
 select id into v_id from public.company_statements where company_id=p_company_id and review_id=p_review_id::text and status='published' order by updated_at desc limit 1 for update;
 if v_id is null then
   insert into public.company_statements(company_id,user_id,review_id,statement,status) values(p_company_id,p_user_id,p_review_id::text,btrim(p_statement),'published') returning id into v_id;
 else
   update public.company_statements set user_id=p_user_id,statement=btrim(p_statement),updated_at=now() where id=v_id;
 end if;
 perform set_config('otzovik.native_mirror','off',true);
 return v_id;
exception when others then perform set_config('otzovik.native_mirror','off',true); raise;
end $function$

CREATE OR REPLACE FUNCTION private.phase8b_acceptance_harness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare
  c1 uuid; c2 uuid; slug1 text;
  legacy_id uuid; qid uuid; msgid uuid;
  before_qr int; before_sr int; after_qr int; after_sr int;
  pub jsonb;
  cross_tenant_rejected boolean := false;
  private_leak boolean := false;
  result jsonb;
begin
  begin
    select id,slug into c1,slug1 from public.companies where status='active' order by id limit 1;
    select id into c2 from public.companies where status='active' and id<>c1 order by id limit 1;
    if c1 is null or c2 is null then raise exception 'need_two_active_companies'; end if;

    insert into public.company_questions_answers(
      company_id,question,answer,status,answered_at,published_at,source_system,provenance
    ) values(
      c1,'PHASE8B synthetic question?','PHASE8B synthetic official answer','published',now(),now(),'phase8b_acceptance','{}'::jsonb
    ) returning id into legacy_id;

    select id into qid
    from private.questions_v1
    where company_id=c1 and legacy_qna_id=legacy_id;

    if qid is null then raise exception 'question_dual_write_missing'; end if;

    select count(*) into before_qr from private.question_revisions_v1 where company_id=c1 and question_id=qid;
    select count(*) into before_sr
    from private.statement_revisions_v2 sr
    join private.official_statements_v2 os on os.company_id=sr.company_id and os.id=sr.official_statement_id
    where os.company_id=c1 and os.question_id=qid;

    update public.company_questions_answers
    set updated_at=now()
    where id=legacy_id and company_id=c1;

    select count(*) into after_qr from private.question_revisions_v1 where company_id=c1 and question_id=qid;
    select count(*) into after_sr
    from private.statement_revisions_v2 sr
    join private.official_statements_v2 os on os.company_id=sr.company_id and os.id=sr.official_statement_id
    where os.company_id=c1 and os.question_id=qid;

    if before_qr<>after_qr or before_sr<>after_sr then raise exception 'idempotency_failed'; end if;

    insert into private.question_messages_v1(
      company_id,question_id,body_original,body_public,language,content_hash,visibility
    ) values(
      c1,qid,'PHASE8B_PRIVATE_SECRET','PHASE8B_PRIVATE_SECRET','ru',
      encode(extensions.digest('PHASE8B_PRIVATE_SECRET','sha256'),'hex'),'private'
    ) returning id into msgid;

    pub := public.get_public_company_content_v1(slug1);
    private_leak := position('PHASE8B_PRIVATE_SECRET' in coalesce(pub::text,''))>0;
    if private_leak then raise exception 'private_message_leaked'; end if;
    if position('PHASE8B synthetic official answer' in coalesce(pub::text,''))=0 then
      raise exception 'official_answer_not_public';
    end if;

    begin
      insert into private.question_messages_v1(
        company_id,question_id,body_original,body_public,language,content_hash,visibility
      ) values(
        c2,qid,'cross tenant','cross tenant','ru',
        encode(extensions.digest('cross tenant','sha256'),'hex'),'private'
      );
    exception when foreign_key_violation then
      cross_tenant_rejected := true;
    end;
    if not cross_tenant_rejected then raise exception 'tenant_isolation_failed'; end if;

    result := jsonb_build_object(
      'status','PASS',
      'question_created',true,
      'official_answer_public',true,
      'private_message_non_leakage',not private_leak,
      'tenant_isolation',cross_tenant_rejected,
      'idempotency',before_qr=after_qr and before_sr=after_sr,
      'question_revision_count',after_qr,
      'statement_revision_count',after_sr
    );

    raise exception using errcode='P0001', message='ROLLBACK_PHASE8B_FIXTURE', detail=result::text;
  exception when sqlstate 'P0001' then
    get stacked diagnostics result = PG_EXCEPTION_DETAIL;
  end;

  return result;
end
$function$

CREATE OR REPLACE FUNCTION private.phase8c_knowledge_acceptance_harness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare c1 uuid;c2 uuid;concept uuid;ver uuid;variant uuid;pub uuid;actor uuid;person uuid;public_before jsonb;public_after jsonb;cross_rejected boolean:=false;result jsonb;
begin begin
 select id into c1 from public.companies where status='active' order by id limit 1; select id into c2 from public.companies where status='active' and id<>c1 order by id limit 1;
 insert into private.persons default values returning id into person;
 insert into private.actors(actor_type,person_id,external_ref,display_label) values('human',person,'phase8c-fixture','Phase 8C fixture') returning id into actor;
 insert into private.knowledge_concepts_v1(company_id,concept_type,scope_type,authority,status) values(c1,'faq','company','native','active') returning id into concept;
 insert into private.knowledge_versions_v1(company_id,concept_id,version,source_language,source_title,source_body,content_checksum,status) values(c1,concept,1,'ru','PHASE8C','PHASE8C_UNVERIFIED_SECRET',encode(extensions.digest('PHASE8C_UNVERIFIED_SECRET','sha256'),'hex'),'current') returning id into ver;
 insert into private.knowledge_variants_v1(company_id,version_id,language,title,body,origin,source_checksum,verification_status) values(c1,ver,'ru','PHASE8C','PHASE8C_UNVERIFIED_SECRET','human',encode(extensions.digest('PHASE8C_UNVERIFIED_SECRET','sha256'),'hex'),'unverified') returning id into variant;
 public_before:=private.get_public_knowledge_v1(c1); if position('PHASE8C_UNVERIFIED_SECRET' in public_before::text)>0 then raise exception 'unverified_leaked'; end if;
 begin insert into private.knowledge_publications_v1(company_id,concept_id,variant_id,audience,language,status) values(c2,concept,variant,'public','ru','published'); exception when foreign_key_violation then cross_rejected:=true; end;
 if not cross_rejected then raise exception 'tenant_isolation_failed'; end if;
 update private.knowledge_variants_v1 set verification_status='verified',verified_by_actor_id=actor,verified_at=now() where id=variant and company_id=c1;
 insert into private.knowledge_publications_v1(company_id,concept_id,variant_id,audience,language,status) values(c1,concept,variant,'public','ru','published') returning id into pub;
 public_after:=private.get_public_knowledge_v1(c1); if position('PHASE8C_UNVERIFIED_SECRET' in public_after::text)=0 then raise exception 'verified_publish_missing'; end if;
 result:=jsonb_build_object('status','PASS','unverified_non_public',true,'tenant_isolation',cross_rejected,'human_verifier_required',true,'verified_publish_visible',true);
 raise exception using errcode='P0001',message='ROLLBACK_PHASE8C_FIXTURE',detail=result::text;
exception when sqlstate 'P0001' then get stacked diagnostics result=PG_EXCEPTION_DETAIL; end; return result; end $function$

CREATE OR REPLACE FUNCTION private.phase8d_unified_cabinet_acceptance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare c1 uuid;c2 uuid;uid uuid;src uuid;rid uuid;legacy_q uuid;qid uuid;msg uuid;person uuid;actor uuid;kc uuid;kvn uuid;kv uuid;kp uuid;public_payload jsonb;result jsonb;detail_text text;
begin begin
 select cm.company_id,cm.user_id into c1,uid from public.company_memberships cm join public.companies c on c.id=cm.company_id and c.status='active' where cm.verification_status='verified' order by case cm.role when 'owner' then 1 else 2 end limit 1;
 select id into c2 from public.companies where status='active' and id<>c1 order by id limit 1;
 insert into public.review_sources(company_id,name,source_type,profile_url,collection_method,status) values(c1,'Phase8D fixture','other','https://example.invalid/phase8d','manual','published') returning id into src;
 insert into public.reviews(company_id,source_id,source_url,author_display_name,published_at,collected_at,rating,content_hash,status,body) values(c1,src,'https://example.invalid/r','Phase8D',now(),now(),5,encode(extensions.digest('phase8d review','sha256'),'hex'),'published','PHASE8D REVIEW') returning id into rid;
 insert into public.company_statements(company_id,user_id,review_id,statement,status) values(c1,uid,rid::text,'PHASE8D REVIEW RESPONSE','published');
 insert into public.company_questions_answers(company_id,question,answer,status,answered_at,published_at,source_system,provenance) values(c1,'PHASE8D QUESTION','PHASE8D ANSWER','published',now(),now(),'phase8d','{}') returning id into legacy_q;
 select id into qid from private.questions_v1 where company_id=c1 and legacy_qna_id=legacy_q;
 insert into private.question_messages_v1(company_id,question_id,body_original,body_public,language,content_hash,visibility) values(c1,qid,'PHASE8D PRIVATE','PHASE8D PRIVATE','ru',encode(extensions.digest('PHASE8D PRIVATE','sha256'),'hex'),'private') returning id into msg;
 insert into private.persons default values returning id into person; insert into private.actors(actor_type,person_id,external_ref,display_label) values('human',person,'phase8d','Phase8D') returning id into actor;
 insert into private.knowledge_concepts_v1(company_id,concept_type,scope_type,authority,status) values(c1,'faq','company','native','active') returning id into kc;
 insert into private.knowledge_versions_v1(company_id,concept_id,version,source_language,source_body,content_checksum,status) values(c1,kc,1,'ru','PHASE8D KNOWLEDGE',encode(extensions.digest('PHASE8D KNOWLEDGE','sha256'),'hex'),'current') returning id into kvn;
 insert into private.knowledge_variants_v1(company_id,version_id,language,body,origin,source_checksum,verification_status,verified_by_actor_id,verified_at) values(c1,kvn,'ru','PHASE8D KNOWLEDGE','human',encode(extensions.digest('PHASE8D KNOWLEDGE','sha256'),'hex'),'verified',actor,now()) returning id into kv;
 insert into private.knowledge_publications_v1(company_id,concept_id,variant_id,audience,language,status) values(c1,kc,kv,'public','ru','published') returning id into kp;
 public_payload:=public.get_public_company_content_v1((select slug from public.companies where id=c1));
 if position('PHASE8D PRIVATE' in public_payload::text)>0 then raise exception 'private_leak'; end if;
 if position('PHASE8D ANSWER' in public_payload::text)=0 then raise exception 'qna_projection_missing'; end if;
 if position('PHASE8D KNOWLEDGE' in public_payload::text)=0 then raise exception 'knowledge_projection_missing'; end if;
 if position('PHASE8D REVIEW RESPONSE' in public_payload::text)=0 then raise exception 'review_response_projection_missing'; end if;
 result:=jsonb_build_object('status','PASS','reviews',true,'questions',true,'knowledge',true,'private_non_leakage',true,'tenant_scoped',true);
 raise exception using errcode='P0001',message='ROLLBACK_PHASE8D_FIXTURE',detail=result::text;
exception when sqlstate 'P0001' then get stacked diagnostics detail_text=PG_EXCEPTION_DETAIL; return detail_text::jsonb; end; end $function$

CREATE OR REPLACE FUNCTION private.request_native_content_profile_publish_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_company_id uuid; v_slug text; v_state text; v_headers jsonb; v_auth text;
begin
 v_company_id:=case when tg_op='DELETE' then old.company_id else new.company_id end;
 if v_company_id is null then return coalesce(new,old); end if;
 select c.slug,coalesce(a.state,'disabled') into v_slug,v_state from public.companies c left join public.company_profile_public_access a on a.company_id=c.id where c.id=v_company_id and c.status='active';
 if v_slug is null or v_state<>'active' then return coalesce(new,old); end if;
 begin v_headers:=nullif(current_setting('request.headers',true),'')::jsonb; v_auth:=v_headers->>'authorization'; exception when others then v_auth:=null; end;
 if v_auth is null or v_auth not like 'Bearer %' then return coalesce(new,old); end if;
 perform net.http_post(url:='https://rzhlcszqtuhkhfibygnk.supabase.co/functions/v1/request-profile-publish',body:=jsonb_build_object('slug',v_slug),headers:=jsonb_build_object('Content-Type','application/json','Authorization',v_auth),timeout_milliseconds:=5000);
 return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION private.run_data_model_v1_acceptance_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public'
AS $function$
declare c1 uuid; c2 uuid; src uuid; r uuid:=gen_random_uuid(); rr uuid:=gen_random_uuid(); q uuid:=gen_random_uuid(); qr uuid:=gen_random_uuid(); qm uuid:=gen_random_uuid(); osr uuid:=gen_random_uuid(); osq uuid:=gen_random_uuid(); srr uuid:=gen_random_uuid(); srq uuid:=gen_random_uuid(); kc uuid:=gen_random_uuid(); kv uuid:=gen_random_uuid(); kvar uuid:=gen_random_uuid(); kp uuid:=gen_random_uuid(); bad_failed boolean:=false; pub jsonb; result jsonb;
begin
 select id into c1 from public.companies where slug='ortomediya'; select id into c2 from public.companies where slug='student-agency'; src:=private.acceptance_pick_source_v1(c1);
 if c1 is null or c2 is null or src is null then raise exception 'fixture prerequisites missing'; end if;
 insert into public.reviews(id,company_id,source_id,source_review_id,source_url,author_display_name,published_at,collected_at,rating,rating_scale,body,language,content_hash,provenance,status) values(r,c1,src,'acceptance-'||r::text,'https://example.invalid/acceptance/'||r::text,'Acceptance Author',now(),now(),5,5,'legacy fixture body','ru',md5('legacy fixture body'),'{"acceptance":true}'::jsonb,'published');
 insert into private.review_revisions_v1(id,company_id,review_id,version,body_original,body_public,language,content_hash,provenance) values(rr,c1,r,1,'revision fixture body','revision fixture body','ru',md5('revision fixture body'),'{"acceptance":true}'::jsonb);
 insert into private.official_statements_v2(id,company_id,review_id) values(osr,c1,r);
 insert into private.statement_revisions_v2(id,company_id,official_statement_id,version,body,status,responds_to_review_revision_id,provenance,published_at) values(srr,c1,osr,1,'official fixture response','published',rr,'{"acceptance":true}'::jsonb,now()); update private.official_statements_v2 set current_published_revision_id=srr where id=osr;
 insert into private.questions_v1(id,company_id,status) values(q,c1,'answered');
 insert into private.question_revisions_v1(id,company_id,question_id,version,body_original,body_public,language,content_hash,provenance) values(qr,c1,q,1,'private fixture question','public fixture question','ru',md5('private fixture question'),'{"acceptance":true}'::jsonb); update private.questions_v1 set current_revision_id=qr,answered_at=now() where id=q;
 insert into private.question_messages_v1(id,company_id,question_id,body_original,body_public,language,content_hash) values(qm,c1,q,'SECRET PRIVATE CLARIFICATION','SECRET PRIVATE CLARIFICATION','ru',md5('SECRET PRIVATE CLARIFICATION'));
 insert into private.official_statements_v2(id,company_id,question_id) values(osq,c1,q);
 insert into private.statement_revisions_v2(id,company_id,official_statement_id,version,body,status,provenance,published_at) values(srq,c1,osq,1,'official fixture answer','published','{"acceptance":true}'::jsonb,now()); update private.official_statements_v2 set current_published_revision_id=srq where id=osq;
 insert into private.knowledge_concepts_v1(id,company_id,concept_type,scope_type,authority) values(kc,c1,'faq','company','native');
 insert into private.knowledge_versions_v1(id,company_id,concept_id,version,source_language,source_title,source_body,content_checksum,status) values(kv,c1,kc,1,'ru','fixture title','fixture knowledge',md5('fixture knowledge'),'current');
 insert into private.knowledge_variants_v1(id,company_id,version_id,language,title,body,origin,source_checksum,verification_status) values(kvar,c1,kv,'ru','fixture title','fixture knowledge','human',md5('fixture knowledge'),'unverified');
 insert into private.knowledge_publications_v1(id,company_id,concept_id,variant_id,audience,language,status) values(kp,c1,kc,kvar,'public','ru','published');
 pub:=public.get_public_company_content_v1('ortomediya');
 if not exists(select 1 from jsonb_array_elements(pub->'reviews') x where x->>'id'=r::text and x->>'body'='revision fixture body' and x->'company_response'->>'statement'='official fixture response') then raise exception 'review read mismatch'; end if;
 if not exists(select 1 from jsonb_array_elements(pub->'official_qna') x where x->>'id'=q::text and x->>'question'='public fixture question' and x->>'answer'='official fixture answer') then raise exception 'qna read mismatch'; end if;
 if pub::text like '%SECRET PRIVATE CLARIFICATION%' then raise exception 'private message leaked'; end if;
 if exists(select 1 from jsonb_array_elements(pub->'knowledge') x where x->>'concept_id'=kc::text) then raise exception 'unverified knowledge leaked'; end if;
 begin update private.knowledge_variants_v1 set verification_status='verified',verified_at=now() where id=kvar; exception when check_violation then bad_failed:=true; end; if not bad_failed then raise exception 'verified variant accepted without verifier'; end if;
 bad_failed:=false; begin insert into private.question_messages_v1(company_id,question_id,body_original,body_public,content_hash) values(c2,q,'x','x',md5('x')); exception when foreign_key_violation then bad_failed:=true; end; if not bad_failed then raise exception 'cross tenant accepted'; end if;
 result:=jsonb_build_object('status','PASS','review_revision_preferred',true,'official_review_response_visible',true,'official_qna_visible',true,'private_message_hidden',true,'unverified_knowledge_hidden',true,'verified_requires_actor',true,'cross_tenant_fk_rejected',true);
 raise exception using errcode='P0002',message=result::text;
exception when sqlstate 'P0002' then return sqlerrm::jsonb;
end $function$

CREATE OR REPLACE FUNCTION private.sync_legacy_qna_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_q uuid; v_qr uuid; v_os uuid; v_sr uuid; v_qver integer; v_sver integer;
begin
 if current_setting('otzovik.native_mirror',true)='on' then return new; end if;
 if new.status not in ('draft','published','archived') then return new; end if;
 select id into v_q from private.questions_v1 where company_id=new.company_id and legacy_qna_id=new.id limit 1;
 if v_q is null then insert into private.questions_v1(company_id,status,created_at,updated_at,answered_at,legacy_qna_id,category,program_label) values(new.company_id,case when new.status='published' then 'answered' when new.status='archived' then 'archived' else 'pending' end,new.created_at,new.updated_at,new.answered_at,new.id,new.category,new.program_label) returning id into v_q; end if;
 if new.status='archived' then update private.questions_v1 set status='archived',updated_at=new.updated_at where id=v_q and company_id=new.company_id; return new; end if;
 select id into v_qr from private.question_revisions_v1 where company_id=new.company_id and question_id=v_q and body_public=new.question order by version desc limit 1;
 if v_qr is null then select coalesce(max(version),0)+1 into v_qver from private.question_revisions_v1 where company_id=new.company_id and question_id=v_q; insert into private.question_revisions_v1(company_id,question_id,version,body_original,body_public,language,content_hash,provenance,created_at) values(new.company_id,v_q,v_qver,new.question,new.question,'ru',encode(extensions.digest(new.question,'sha256'),'hex'),jsonb_build_object('legacy_qna_id',new.id::text,'source','legacy_qna_sync'),new.updated_at) returning id into v_qr; end if;
 update private.questions_v1 set current_revision_id=v_qr,status=case when new.status='published' then 'answered' else 'pending' end,answered_at=new.answered_at,category=coalesce(category,new.category),program_label=coalesce(program_label,new.program_label),updated_at=new.updated_at where id=v_q;
 select id into v_os from private.official_statements_v2 where company_id=new.company_id and question_id=v_q; if v_os is null then insert into private.official_statements_v2(company_id,question_id) values(new.company_id,v_q) returning id into v_os; end if;
 select id into v_sr from private.statement_revisions_v2 where company_id=new.company_id and official_statement_id=v_os and body=new.answer and status=case when new.status='published' then 'published' else 'draft' end order by version desc limit 1;
 if v_sr is null then select coalesce(max(version),0)+1 into v_sver from private.statement_revisions_v2 where company_id=new.company_id and official_statement_id=v_os; if new.status='published' then update private.statement_revisions_v2 set status='superseded' where company_id=new.company_id and official_statement_id=v_os and status='published'; end if; insert into private.statement_revisions_v2(company_id,official_statement_id,version,body,status,provenance,created_at,published_at) values(new.company_id,v_os,v_sver,new.answer,case when new.status='published' then 'published' else 'draft' end,jsonb_build_object('legacy_qna_id',new.id::text,'source','legacy_qna_sync'),new.updated_at,case when new.status='published' then coalesce(new.published_at,new.updated_at) else null end) returning id into v_sr; end if;
 update private.official_statements_v2 set current_draft_revision_id=case when new.status='draft' then v_sr else current_draft_revision_id end,current_published_revision_id=case when new.status='published' then v_sr else current_published_revision_id end,updated_at=new.updated_at where id=v_os;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.sync_statement_v2_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare v_review uuid;v_os uuid;v_rr uuid;v_sr uuid;v_version integer;v_review_row public.reviews%rowtype;
begin
 if new.status <> 'published' then return new; end if;
 v_review:=new.review_id::uuid;
 select * into v_review_row from public.reviews where company_id=new.company_id and id=v_review;
 if not found then return new; end if;
 select id into v_rr from private.review_revisions_v1 where company_id=new.company_id and review_id=v_review order by version desc limit 1;
 if v_rr is null then
   insert into private.review_revisions_v1(company_id,review_id,version,body_original,body_public,language,content_hash,provenance)
   values(new.company_id,v_review,1,v_review_row.body,v_review_row.body,v_review_row.language,
          encode(extensions.digest(v_review_row.body,'sha256'),'hex'),
          jsonb_build_object('source','legacy_review_compat','review_id',v_review::text))
   returning id into v_rr;
 end if;
 select id into v_os from private.official_statements_v2 where company_id=new.company_id and review_id=v_review;
 if v_os is null then insert into private.official_statements_v2(company_id,review_id) values(new.company_id,v_review) returning id into v_os; end if;
 select id into v_sr from private.statement_revisions_v2 where company_id=new.company_id and official_statement_id=v_os and provenance->>'legacy_id'=new.id::text limit 1;
 if v_sr is null then
   select coalesce(max(version),0)+1 into v_version from private.statement_revisions_v2 where company_id=new.company_id and official_statement_id=v_os;
   update private.statement_revisions_v2 set status='superseded' where company_id=new.company_id and official_statement_id=v_os and status='published';
   insert into private.statement_revisions_v2(company_id,official_statement_id,version,body,status,responds_to_review_revision_id,provenance,published_at)
   values(new.company_id,v_os,v_version,new.statement,'published',v_rr,jsonb_build_object('legacy_id',new.id::text,'source','legacy_company_statement'),new.updated_at) returning id into v_sr;
 else
   update private.statement_revisions_v2 set body=new.statement,published_at=new.updated_at,responds_to_review_revision_id=v_rr where id=v_sr;
 end if;
 update private.official_statements_v2 set current_published_revision_id=v_sr,updated_at=now() where id=v_os;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.write_native_qna_v1(p_company_id uuid, p_question_id uuid, p_question text, p_answer text, p_category text, p_program_label text, p_publish boolean, p_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_q uuid:=p_question_id; v_qr uuid; v_os uuid; v_sr uuid; v_qver int; v_sver int; v_status text:=case when p_publish then 'answered' else 'pending' end;
begin
 if char_length(btrim(coalesce(p_question,''))) not between 3 and 2000 then raise exception 'invalid_question' using errcode='22023'; end if;
 if char_length(btrim(coalesce(p_answer,''))) not between 1 and 10000 then raise exception 'invalid_answer' using errcode='22023'; end if;
 if v_q is null then
   insert into private.questions_v1(company_id,status,category,program_label,answered_at)
   values(p_company_id,v_status,nullif(btrim(p_category),''),nullif(btrim(p_program_label),''),case when p_publish then now() else null end) returning id into v_q;
 else
   if not exists(select 1 from private.questions_v1 where id=v_q and company_id=p_company_id) then raise exception 'question_not_found' using errcode='P0002'; end if;
   update private.questions_v1 set status=v_status,category=nullif(btrim(p_category),''),program_label=nullif(btrim(p_program_label),''),answered_at=case when p_publish then coalesce(answered_at,now()) else null end,updated_at=now() where id=v_q and company_id=p_company_id;
 end if;
 select coalesce(max(version),0)+1 into v_qver from private.question_revisions_v1 where company_id=p_company_id and question_id=v_q;
 insert into private.question_revisions_v1(company_id,question_id,version,body_original,body_public,language,content_hash,provenance)
 values(p_company_id,v_q,v_qver,btrim(p_question),btrim(p_question),'ru',encode(extensions.digest(btrim(p_question),'sha256'),'hex'),jsonb_build_object('source','phase9a_native_writer','actor_user_id',p_user_id,'actor_role',p_role)) returning id into v_qr;
 update private.questions_v1 set current_revision_id=v_qr,updated_at=now() where id=v_q and company_id=p_company_id;
 select id into v_os from private.official_statements_v2 where company_id=p_company_id and question_id=v_q limit 1 for update;
 if v_os is null then insert into private.official_statements_v2(company_id,question_id) values(p_company_id,v_q) returning id into v_os; end if;
 select coalesce(max(version),0)+1 into v_sver from private.statement_revisions_v2 where company_id=p_company_id and official_statement_id=v_os;
 if p_publish then update private.statement_revisions_v2 set status='superseded' where company_id=p_company_id and official_statement_id=v_os and status='published';
 else update private.statement_revisions_v2 set status='superseded' where company_id=p_company_id and official_statement_id=v_os and status='draft'; end if;
 insert into private.statement_revisions_v2(company_id,official_statement_id,version,body,status,provenance,published_at)
 values(p_company_id,v_os,v_sver,btrim(p_answer),case when p_publish then 'published' else 'draft' end,jsonb_build_object('source','phase9a_native_writer','actor_user_id',p_user_id,'actor_role',p_role),case when p_publish then now() else null end) returning id into v_sr;
 update private.official_statements_v2 set current_published_revision_id=case when p_publish then v_sr else current_published_revision_id end,current_draft_revision_id=case when p_publish then null else v_sr end,updated_at=now() where id=v_os and company_id=p_company_id;
 return jsonb_build_object('question_id',v_q,'question_revision_id',v_qr,'statement_revision_id',v_sr,'status',case when p_publish then 'published' else 'draft' end);
end $function$

CREATE OR REPLACE FUNCTION private.write_native_review_response_v1(p_company_id uuid, p_review_id uuid, p_body text, p_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_os uuid; v_rr uuid; v_sr uuid; v_ver int;
begin
 if char_length(btrim(coalesce(p_body,''))) not between 1 and 5000 then raise exception 'invalid_statement' using errcode='22023'; end if;
 if not exists(select 1 from public.reviews r where r.id=p_review_id and r.company_id=p_company_id and r.status='published') then raise exception 'review_not_found' using errcode='P0002'; end if;
 select rr.id into v_rr from private.review_revisions_v1 rr where rr.company_id=p_company_id and rr.review_id=p_review_id and rr.erased_at is null order by rr.version desc limit 1;
 if v_rr is null then
   insert into private.review_revisions_v1(company_id,review_id,version,body_original,body_public,language,content_hash,provenance)
   select r.company_id,r.id,1,r.body,r.body,coalesce(r.language,'ru'),encode(extensions.digest(coalesce(r.body,''),'sha256'),'hex'),jsonb_build_object('source','phase9a_review_compat')
   from public.reviews r where r.id=p_review_id and r.company_id=p_company_id returning id into v_rr;
 end if;
 select id into v_os from private.official_statements_v2 where company_id=p_company_id and review_id=p_review_id limit 1 for update;
 if v_os is null then insert into private.official_statements_v2(company_id,review_id) values(p_company_id,p_review_id) returning id into v_os; end if;
 select coalesce(max(version),0)+1 into v_ver from private.statement_revisions_v2 where company_id=p_company_id and official_statement_id=v_os;
 update private.statement_revisions_v2 set status='superseded' where company_id=p_company_id and official_statement_id=v_os and status='published';
 insert into private.statement_revisions_v2(company_id,official_statement_id,version,body,status,responds_to_review_revision_id,provenance,published_at)
 values(p_company_id,v_os,v_ver,btrim(p_body),'published',v_rr,jsonb_build_object('source','phase9a_native_writer','actor_user_id',p_user_id,'actor_role',p_role),now()) returning id into v_sr;
 update private.official_statements_v2 set current_published_revision_id=v_sr,current_draft_revision_id=null,updated_at=now() where id=v_os and company_id=p_company_id;
 return jsonb_build_object('official_statement_id',v_os,'statement_revision_id',v_sr,'version',v_ver,'status','published');
end $function$

CREATE OR REPLACE FUNCTION public.accept_company_access_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_hash text;
  v_inv public.company_access_invitations%rowtype;
  v_existing_role text;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_token is null or char_length(p_token) < 32 then raise exception 'Invalid invitation token'; end if;

  select lower(email) into v_email from auth.users where id=v_uid;
  if v_email is null then raise exception 'Authenticated email required'; end if;

  v_hash := encode(digest(p_token, 'sha256'), 'hex');
  select * into v_inv from public.company_access_invitations
   where token_hash=v_hash and status='pending'
   for update;
  if not found then raise exception 'Invitation not found or no longer pending'; end if;

  if v_inv.expires_at <= now() then
    update public.company_access_invitations
       set status='expired', updated_at=now()
     where id=v_inv.id;
    return jsonb_build_object('status','expired');
  end if;

  if lower(v_inv.email) <> v_email then raise exception 'Invitation email does not match authenticated user'; end if;

  select role into v_existing_role
    from public.company_memberships
   where company_id=v_inv.company_id and user_id=v_uid;

  if v_existing_role is not null then
    if v_existing_role='owner' then raise exception 'Company owner cannot accept delegated invitation'; end if;
    raise exception 'User already has access to this company';
  end if;

  insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at)
  values(v_inv.company_id,v_uid,v_inv.role,'verified','email_invitation',now());

  update public.company_access_invitations
     set status='accepted', accepted_by=v_uid, accepted_at=now(), updated_at=now()
   where id=v_inv.id;

  return jsonb_build_object('company_id',v_inv.company_id,'role',v_inv.role,'status','accepted');
end $function$

CREATE OR REPLACE FUNCTION public.accept_my_company_invitation(p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid:=auth.uid(); v_email text; v_inv public.company_access_invitations%rowtype;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select lower(email) into v_email from auth.users where id=v_uid;
 select * into v_inv from public.company_access_invitations where id=p_invitation_id and status='pending' for update;
 if not found then raise exception 'Invitation not found or no longer pending'; end if;
 if lower(v_inv.email)<>v_email then raise exception 'Invitation email does not match authenticated user'; end if;
 if v_inv.expires_at<=now() then update public.company_access_invitations set status='expired',updated_at=now() where id=v_inv.id; return jsonb_build_object('status','expired'); end if;
 if exists(select 1 from public.company_memberships where company_id=v_inv.company_id and user_id=v_uid) then raise exception 'User already has access to this company'; end if;
 insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at) values(v_inv.company_id,v_uid,v_inv.role,'verified','account_invitation',now());
 update public.company_access_invitations set status='accepted',accepted_by=v_uid,accepted_at=now(),updated_at=now() where id=v_inv.id;
 return jsonb_build_object('status','accepted','company_id',v_inv.company_id,'role',v_inv.role);
end $function$

CREATE OR REPLACE FUNCTION public.add_my_company_review_source(p_company_id uuid, p_name text, p_profile_url text, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_name text := nullif(btrim(p_name),'');
  v_url text := nullif(btrim(p_profile_url),'');
  v_source_type text;
  v_external_key text;
  v_row public.review_sources%rowtype;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.verification_status='verified' and cm.role in ('owner','admin')
  ) then raise exception 'forbidden' using errcode='42501'; end if;
  if v_name is null or length(v_name)>80 then raise exception 'invalid_source_name' using errcode='22023'; end if;
  if v_url is null or length(v_url)>2048 or v_url !~* '^https://[^[:space:]]+$' then raise exception 'invalid_profile_url' using errcode='22023'; end if;
  if p_location_id is not null and not exists (
    select 1 from public.company_locations cl where cl.id=p_location_id and cl.company_id=p_company_id
  ) then raise exception 'invalid_location' using errcode='22023'; end if;

  v_source_type := case
    when v_url ~* '^https://([^/]+\.)?2gis\.' then '2gis'
    when v_url ~* '^https://([^/]+\.)?(yandex\.|ya\.ru)' then 'yandex'
    when v_url ~* '^https://([^/]+\.)?(google\.|goo\.gl|maps\.app\.goo\.gl)' then 'google'
    else 'other'
  end;

  v_external_key := case
    when v_source_type='2gis' then (regexp_match(v_url, '/firm/([0-9]+)', 'i'))[1]
    when v_source_type='yandex' then (regexp_match(v_url, '/org/(?:[^/?#]+/)?([0-9]+)(?:[/?#]|$)', 'i'))[1]
    else null
  end;

  select * into v_row from public.review_sources
   where company_id=p_company_id and profile_url=v_url limit 1 for update;

  if found and v_row.status <> 'archived' then
    return jsonb_build_object('id',v_row.id,'company_id',v_row.company_id,'location_id',v_row.location_id,'name',v_row.name,'source_type',v_row.source_type,'profile_url',v_row.profile_url,'status',v_row.status,'checked_at',v_row.checked_at,'updated_at',v_row.updated_at,'duplicate',true,'duplicate_kind','exact_url','reactivated',false);
  elsif found then
    update public.review_sources
       set location_id=p_location_id,name=v_name,source_type=v_source_type,
           collection_method='owner_submitted',terms_notes=null,status='draft',
           checked_at=null,updated_at=now()
     where id=v_row.id returning * into v_row;
    return jsonb_build_object('id',v_row.id,'company_id',v_row.company_id,'location_id',v_row.location_id,'name',v_row.name,'source_type',v_row.source_type,'profile_url',v_row.profile_url,'status',v_row.status,'checked_at',v_row.checked_at,'updated_at',v_row.updated_at,'duplicate',false,'duplicate_kind',null,'reactivated',true);
  end if;

  if v_external_key is not null then
    select rs.* into v_row from public.review_sources rs
    where rs.company_id=p_company_id and rs.status <> 'archived'
      and rs.location_id is not distinct from p_location_id
      and (case when rs.profile_url ~* '^https://([^/]+\.)?2gis\.' then '2gis' when rs.profile_url ~* '^https://([^/]+\.)?(yandex\.|ya\.ru)' then 'yandex' else rs.source_type end)=v_source_type
      and (case when v_source_type='2gis' then (regexp_match(rs.profile_url, '/firm/([0-9]+)', 'i'))[1] when v_source_type='yandex' then (regexp_match(rs.profile_url, '/org/(?:[^/?#]+/)?([0-9]+)(?:[/?#]|$)', 'i'))[1] else null end)=v_external_key
    order by rs.created_at limit 1 for update;
    if found then
      return jsonb_build_object('id',v_row.id,'company_id',v_row.company_id,'location_id',v_row.location_id,'name',v_row.name,'source_type',v_row.source_type,'profile_url',v_row.profile_url,'status',v_row.status,'checked_at',v_row.checked_at,'updated_at',v_row.updated_at,'duplicate',true,'duplicate_kind','listing_id','reactivated',false,'external_key',v_external_key);
    end if;
  end if;

  insert into public.review_sources(company_id,location_id,name,source_type,profile_url,collection_method,terms_notes,status,checked_at,updated_at)
  values(p_company_id,p_location_id,v_name,v_source_type,v_url,'owner_submitted',null,'draft',null,now())
  returning * into v_row;

  return jsonb_build_object('id',v_row.id,'company_id',v_row.company_id,'location_id',v_row.location_id,'name',v_row.name,'source_type',v_row.source_type,'profile_url',v_row.profile_url,'status',v_row.status,'checked_at',v_row.checked_at,'updated_at',v_row.updated_at,'duplicate',false,'duplicate_kind',null,'reactivated',false,'external_key',v_external_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_yookassa_payment_status(p_order_id uuid, p_provider_payment_id text, p_status text, p_paid boolean, p_amount_rub integer, p_currency text, p_test boolean, p_payment_method_type text, p_provider_created_at timestamp with time zone, p_raw_status jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_now timestamptz := now();
  v_period_end timestamptz;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order_not_found';
  end if;
  if v_order.amount_rub <> p_amount_rub or p_currency <> 'RUB' then
    raise exception 'payment_amount_mismatch';
  end if;
  if v_order.provider_payment_id is not null and v_order.provider_payment_id <> p_provider_payment_id then
    raise exception 'provider_payment_mismatch';
  end if;

  insert into public.payments(
    order_id, provider_payment_id, amount_rub, currency, status, paid, test,
    payment_method_type, provider_created_at, confirmed_at, raw_status, updated_at
  ) values (
    p_order_id, p_provider_payment_id, p_amount_rub, p_currency, p_status, p_paid, p_test,
    p_payment_method_type, p_provider_created_at,
    case when p_status='succeeded' and p_paid then v_now else null end,
    coalesce(p_raw_status,'{}'::jsonb), v_now
  )
  on conflict (provider_payment_id) do update set
    status=excluded.status,
    paid=excluded.paid,
    test=excluded.test,
    payment_method_type=excluded.payment_method_type,
    provider_created_at=excluded.provider_created_at,
    confirmed_at=coalesce(public.payments.confirmed_at, excluded.confirmed_at),
    raw_status=excluded.raw_status,
    updated_at=v_now;

  update public.orders set
    provider_payment_id=p_provider_payment_id,
    status=case
      when p_status='succeeded' and p_paid then 'paid'
      when p_status='canceled' then 'canceled'
      else 'payment_pending'
    end,
    paid_at=case when p_status='succeeded' and p_paid then coalesce(paid_at,v_now) else paid_at end
  where id=p_order_id;

  if p_status='succeeded' and p_paid then
    v_period_end := v_now + interval '1 month';

    insert into public.subscriptions(company_id,plan_code,status,current_period_start,current_period_end,provider,provider_subscription_id,updated_at)
    values(v_order.company_id,v_order.plan_code,'active',v_now,v_period_end,'yookassa',p_provider_payment_id,v_now)
    on conflict (company_id) where status in ('active','past_due','grace_period')
    do update set
      plan_code=excluded.plan_code,
      status='active',
      current_period_start=v_now,
      current_period_end=v_period_end,
      provider='yookassa',
      provider_subscription_id=p_provider_payment_id,
      updated_at=v_now;

    update public.entitlements set enabled=false, expires_at=v_now
    where company_id=v_order.company_id and source='subscription';

    insert into public.entitlements(company_id,key,enabled,source,expires_at)
    select v_order.company_id, pe.entitlement_key, true, 'subscription', v_period_end
    from public.plan_entitlements pe
    where pe.plan_code=v_order.plan_code
    on conflict (company_id,key) do update set
      enabled=true, source='subscription', expires_at=v_period_end;
  end if;

  return jsonb_build_object('order_id',p_order_id,'status',p_status,'paid',p_paid);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_my_company_review_source(p_company_id uuid, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_row public.review_sources%rowtype; v_cancelled int:=0;
begin
 if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
 if not exists(select 1 from public.company_memberships cm where cm.company_id=p_company_id and cm.user_id=v_uid and cm.verification_status='verified' and cm.role in ('owner','admin')) then raise exception 'forbidden' using errcode='42501'; end if;
 select * into v_row from public.review_sources where id=p_source_id and company_id=p_company_id for update;
 if not found then raise exception 'source_not_found' using errcode='P0002'; end if;
 update public.review_sources set status='archived',updated_at=now() where id=v_row.id;
 update private.review_source_sync_jobs set status='failed',finished_at=now(),updated_at=now(),error_code='source_archived',error_message='Source archived by owner before sync completion'
 where source_id=v_row.id and status in ('pending','running');
 get diagnostics v_cancelled = row_count;
 return jsonb_build_object('id',v_row.id,'company_id',v_row.company_id,'status','archived','cancelled_sync_jobs',v_cancelled);
end;$function$

CREATE OR REPLACE FUNCTION public.check_own_review_rate_limit_internal(p_company_slug text, p_source_ip_hash text, p_limit integer DEFAULT 5, p_window_seconds integer DEFAULT 3600)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_company_id uuid;
  v_count integer;
begin
  if p_limit < 1 or p_limit > 100 or p_window_seconds < 60 or p_window_seconds > 86400 then
    raise exception 'invalid rate limit policy';
  end if;
  if p_source_ip_hash is null or p_source_ip_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid source hash';
  end if;
  select c.id into v_company_id
  from public.companies c
  join public.company_profile_public_access a on a.company_id=c.id
  where c.slug=p_company_slug
    and c.status='active'
    and c.profile_status='ready'
    and a.state='active'
    and a.review_intake_enabled is true;
  if v_company_id is null then return false; end if;

  delete from private.own_review_rate_limits
   where created_at < now() - interval '2 days';

  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text || ':' || p_source_ip_hash, 0));
  select count(*) into v_count
    from private.own_review_rate_limits
   where company_id=v_company_id
     and source_ip_hash=p_source_ip_hash
     and created_at >= now() - make_interval(secs => p_window_seconds);
  if v_count >= p_limit then return false; end if;
  insert into private.own_review_rate_limits(company_id,source_ip_hash)
  values(v_company_id,p_source_ip_hash);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_company(p_name text, p_slug text, p_website text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_company_id uuid;
  v_membership_id uuid;
  v_existing_id uuid;
  v_existing_slug text;
  v_name text := btrim(coalesce(p_name,''));
  v_base_slug text := lower(btrim(coalesce(p_slug,'')));
  v_slug text;
  v_suffix integer := 0;
  v_website text := nullif(btrim(coalesce(p_website,'')),'');
  v_website_host text;
  v_default_website boolean;
  v_constraint text;
  v_phone text := nullif(btrim(coalesce(p_phone,'')),'');
  v_city text := nullif(btrim(coalesce(p_city,'')),'');
  v_email text := nullif(lower(btrim(coalesce(p_email,''))),'');
begin
  if v_user_id is null then
    raise exception using errcode='42501', message='Authentication required';
  end if;
  if v_name='' or char_length(v_name)>200 then
    raise exception using errcode='22023', message='Company name must contain 1-200 characters';
  end if;
  if v_base_slug !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$' then
    raise exception using errcode='22023', message='Invalid company slug';
  end if;
  if v_base_slug in ('www','api','admin','test','test2','account','login','profiles','specialists') then
    raise exception using errcode='22023', message='Reserved company slug';
  end if;

  v_default_website := v_website IS NULL OR v_website IN (
    'https://' || v_base_slug || '.xn--b1ajuq0c.com/',
    'https://' || v_base_slug || '.отзыв.com/');
  if NOT v_default_website then
    v_website_host := lower(regexp_replace(regexp_replace(v_website,'^https?://','','i'),'/.*$',''));
    v_website_host := regexp_replace(v_website_host,'^www\.','','i');
  end if;

  select c.id,c.slug into v_existing_id,v_existing_slug
  from public.companies c
  where c.status <> 'archived'
    and (
      (v_website_host is not null and
       regexp_replace(lower(regexp_replace(regexp_replace(coalesce(c.website,''),'^https?://','','i'),'/.*$','')),'^www\.','','i') = v_website_host)
      or
      (lower(btrim(c.name))=lower(v_name)
       and lower(btrim(coalesce(c.city,'')))=lower(btrim(coalesce(v_city,'')))
       and coalesce(v_city,'')<>'')
    )
  order by c.created_at
  limit 1;

  if v_existing_id is not null then
    if exists(select 1 from public.company_memberships m where m.company_id=v_existing_id and m.user_id=v_user_id and m.verification_status<>'revoked') then
      raise exception using errcode='23505', message='Company already exists in your account';
    end if;
    raise exception using errcode='23505', message='Company already exists';
  end if;

  loop
    v_slug := case when v_suffix=0 then v_base_slug else rtrim(left(v_base_slug, 63 - 1 - char_length((v_suffix+1)::text)), '-')||'-'||(v_suffix+1)::text end;
    if char_length(v_slug)>63 OR v_suffix > 100 then
      raise exception using errcode='22023', message='No available company slug';
    end if;
    IF v_default_website THEN
      v_website := 'https://' || v_slug || '.xn--b1ajuq0c.com/';
    END IF;
    begin
      insert into public.companies(slug,name,website,phone,city,email,status,profile_status)
      values(v_slug,v_name,v_website,v_phone,v_city,v_email,'active','ready')
      returning id into v_company_id;
      exit;
    exception when unique_violation then
      GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
      IF v_constraint NOT IN ('companies_slug_key','profile_slug_registry_pkey') THEN RAISE; END IF;
      v_suffix:=v_suffix+1;
    end;
  end loop;

  insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at)
  values(v_company_id,v_user_id,'owner','verified','creator',now())
  returning id into v_membership_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(v_company_id,v_user_id,'company_created','company',v_company_id::text,
    jsonb_build_object('slug',v_slug,'role','owner','verification_method','creator'));

  return jsonb_build_object(
    'company',jsonb_build_object('id',v_company_id,'slug',v_slug,'public_url','https://'||v_slug||'.xn--b1ajuq0c.com/','name',v_name,'website',v_website,'phone',v_phone,'city',v_city,'email',v_email,'status','active','profile_status','ready'),
    'membership',jsonb_build_object('id',v_membership_id,'role','owner','verification_status','verified')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_company_location(p_company_id uuid, p_name text, p_address text, p_city text, p_phone text DEFAULT NULL::text, p_hours jsonb DEFAULT '{}'::jsonb, p_official_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
  v_role text;
begin
  if v_user is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select role into v_role
  from public.company_memberships
  where company_id = p_company_id
    and user_id = v_user
    and verification_status = 'verified'
    and role in ('owner','admin')
  limit 1;

  if v_role is null then
    raise exception 'verified_owner_or_admin_required' using errcode='42501';
  end if;

  if nullif(trim(coalesce(p_name,'')),'') is null
     or nullif(trim(coalesce(p_address,'')),'') is null
     or nullif(trim(coalesce(p_city,'')),'') is null then
    raise exception 'name_address_city_required' using errcode='22023';
  end if;

  insert into public.company_locations(
    company_id, name, relationship_type, canonical_address, city,
    phone, hours, official_url, source_url, status, verified_at
  )
  values(
    p_company_id, trim(p_name), 'owned', trim(p_address), trim(p_city),
    nullif(trim(coalesce(p_phone,'')),''),
    coalesce(p_hours,'{}'::jsonb),
    nullif(trim(coalesce(p_official_url,'')),''),
    'owner-submitted', 'published', now()
  )
  returning id into v_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(
    p_company_id, v_user, 'company_location.created', 'location', v_id,
    jsonb_build_object('role',v_role)
  );

  return jsonb_build_object('id',v_id,'company_id',p_company_id);
end;
$function$

