    'membership',jsonb_build_object('role',v_role,'verification_status',v_verification_status),
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'relationship_type',l.relationship_type,'canonical_address',l.canonical_address,'city',l.city,'phone',l.phone,'hours',l.hours,'official_url',l.official_url,'latitude',l.latitude,'longitude',l.longitude,'status',l.status,'verified_at',l.verified_at,'updated_at',l.updated_at) order by l.name) from public.company_locations l where l.company_id=v_company_id and l.status='active'),'[]'::jsonb),
    'services',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'category',s.category,'description',s.description,'official_url',s.official_url,'status',s.status,'verified_at',s.verified_at,'updated_at',s.updated_at) order by s.category,s.name) from public.company_services s where s.company_id=v_company_id and s.status='published'),'[]'::jsonb)
  );
end; $function$

CREATE OR REPLACE FUNCTION public.get_my_company_deletion_plan(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_company public.companies%rowtype;
  v_orders integer;
  v_own_reviews integer;
  v_objects jsonb;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.role='owner' and cm.verification_status='verified'
  ) then raise exception 'owner_required' using errcode='42501'; end if;

  select * into v_company from public.companies where id=p_company_id;
  if not found then raise exception 'company_not_found' using errcode='P0002'; end if;

  select count(*) into v_orders from public.orders where company_id=p_company_id;
  select count(*) into v_own_reviews from private.own_review_submissions where company_id=p_company_id;
  select coalesce(jsonb_agg(so.name order by so.name),'[]'::jsonb) into v_objects
    from storage.objects so
   where so.bucket_id='company-media'
     and (storage.foldername(so.name))[1]=p_company_id::text;

  return jsonb_build_object(
    'company_id',v_company.id,'name',v_company.name,'slug',v_company.slug,
    'public_url','https://'||v_company.slug||'.xn--b1ajuq0c.com/',
    'storage_objects',v_objects,'storage_object_count',jsonb_array_length(v_objects),
    'blockers',jsonb_build_object('orders',v_orders,'own_review_submissions',v_own_reviews),
    'can_delete',(v_orders=0 and v_own_reviews=0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_company_review_sources(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_result jsonb;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.verification_status='verified' and cm.role in ('owner','admin')
  ) then raise exception 'forbidden' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',rs.id,'company_id',rs.company_id,'location_id',rs.location_id,
    'name',rs.name,'source_type',rs.source_type,'profile_url',rs.profile_url,
    'collection_method',rs.collection_method,'status',rs.status,
    'checked_at',rs.checked_at,'updated_at',rs.updated_at,
    'latest_rating',case when sr.id is null then null else jsonb_build_object(
      'rating',sr.rating,'scale',sr.rating_scale,'rating_count',sr.rating_count,
      'review_count',sr.review_count,'checked_at',sr.checked_at,'status',sr.status) end
  ) order by rs.created_at), '[]'::jsonb) into v_result
  from public.review_sources rs
  left join lateral (
    select x.* from public.source_ratings x
    where x.source_id=rs.id and x.status='published'
    order by x.checked_at desc limit 1
  ) sr on true
  where rs.company_id=p_company_id and rs.status <> 'archived';
  return v_result;
end;
$function$

