CREATE OR REPLACE FUNCTION public.record_own_review_ai_assessment_internal(p_submission_id uuid, p_status text, p_risk_score numeric DEFAULT NULL::numeric, p_flags jsonb DEFAULT '[]'::jsonb, p_summary text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_submission private.own_review_submissions%rowtype;
begin
  if p_status not in ('passed','flagged','failed') then raise exception 'invalid_ai_status'; end if;
  if p_risk_score is not null and (p_risk_score < 0 or p_risk_score > 1) then raise exception 'invalid_risk_score'; end if;
  if p_flags is null or jsonb_typeof(p_flags) <> 'array' then raise exception 'invalid_flags'; end if;
  if p_summary is not null and char_length(p_summary) > 2000 then raise exception 'summary_too_long'; end if;

  select s.* into v_submission
  from private.own_review_submissions s
  where s.id=p_submission_id
  for update;
  if not found then raise exception 'submission_not_found' using errcode='P0002'; end if;

  if v_submission.status in ('published','rejected','removed') then
    raise exception 'submission_lifecycle_closed' using errcode='55000';
  end if;

  update private.own_review_submissions
     set ai_moderation_status=p_status,
         ai_risk_score=p_risk_score,
         ai_flags=p_flags,
         ai_summary=p_summary,
         ai_moderated_at=now(),
         updated_at=now()
   where id=p_submission_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(v_submission.company_id,null,'own_review.ai_assessed','own_review_submission',p_submission_id::text,
    jsonb_build_object('ai_status',p_status,'risk_score',p_risk_score,'flags',p_flags));

  return p_submission_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_review_source_rating_snapshot(p_source_id uuid, p_rating numeric, p_rating_scale numeric, p_rating_count integer DEFAULT NULL::integer, p_review_count integer DEFAULT NULL::integer, p_checked_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_source public.review_sources%rowtype;
  v_rating public.source_ratings%rowtype;
begin
  if p_source_id is null then
    raise exception 'source_id_required' using errcode='22023';
  end if;
  if p_rating is null or p_rating_scale is null or p_rating_scale <= 0 or p_rating < 0 or p_rating > p_rating_scale then
    raise exception 'invalid_rating' using errcode='22023';
  end if;
  if p_rating_count is not null and p_rating_count < 0 then
    raise exception 'invalid_rating_count' using errcode='22023';
  end if;
  if p_review_count is not null and p_review_count < 0 then
    raise exception 'invalid_review_count' using errcode='22023';
  end if;
  if p_checked_at is null or p_checked_at > now() + interval '5 minutes' then
    raise exception 'invalid_checked_at' using errcode='22023';
  end if;

  select * into v_source
  from public.review_sources
  where id = p_source_id
  for update;

  if not found then
    raise exception 'review_source_not_found' using errcode='P0002';
  end if;
  if v_source.status = 'archived' then
    raise exception 'review_source_archived' using errcode='55000';
  end if;

  insert into public.source_ratings(
    source_id, rating, rating_scale, rating_count, review_count, checked_at, status
  ) values (
    p_source_id, p_rating, p_rating_scale, p_rating_count, p_review_count, p_checked_at, 'published'
  )
  returning * into v_rating;

  update public.review_sources
  set status = 'published',
      checked_at = p_checked_at,
      updated_at = now()
  where id = p_source_id;

  return jsonb_build_object(
    'source_id', p_source_id,
    'source_status', 'published',
    'rating_id', v_rating.id,
    'rating', v_rating.rating,
    'rating_scale', v_rating.rating_scale,
    'rating_count', v_rating.rating_count,
    'review_count', v_rating.review_count,
    'checked_at', v_rating.checked_at,
    'status', v_rating.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.recover_stale_review_source_sync_jobs(p_stale_after interval DEFAULT '00:15:00'::interval, p_max_attempts integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_requeued int:=0; v_failed int:=0;
begin
 if p_stale_after < interval '1 minute' or p_stale_after > interval '24 hours' then raise exception 'invalid_stale_after' using errcode='22023'; end if;
 if p_max_attempts < 1 or p_max_attempts > 20 then raise exception 'invalid_max_attempts' using errcode='22023'; end if;
 update private.review_source_sync_jobs j
 set status='failed',finished_at=now(),updated_at=now(),error_code='max_attempts_exceeded',error_message='Stale running job exceeded retry limit'
 where j.status='running' and j.started_at < now()-p_stale_after and j.attempt_count>=p_max_attempts;
 get diagnostics v_failed=row_count;
 update private.review_source_sync_jobs j
 set status='pending',started_at=null,finished_at=null,updated_at=now(),error_code='stale_requeued',error_message='Stale running job returned to queue'
 where j.status='running' and j.started_at < now()-p_stale_after and j.attempt_count<p_max_attempts
 and exists(select 1 from public.review_sources rs where rs.id=j.source_id and rs.status<>'archived');
 get diagnostics v_requeued=row_count;
 return jsonb_build_object('requeued',v_requeued,'failed',v_failed);
end;$function$

CREATE OR REPLACE FUNCTION public.register_my_company_media(p_company_id uuid, p_storage_object_name text, p_media_type text, p_alt_text text DEFAULT NULL::text, p_caption text DEFAULT NULL::text, p_sort_order integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_media public.company_media%rowtype;
  v_expected_prefix text;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if p_media_type not in ('logo','cover','interior','exterior','products','team') then
    raise exception 'invalid_media_type' using errcode='22023';
  end if;
  if p_sort_order < 0 then raise exception 'invalid_sort_order' using errcode='22023'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.verification_status='verified' and cm.role in ('owner','admin')
  ) then raise exception 'forbidden' using errcode='42501'; end if;

  v_expected_prefix := p_company_id::text || '/' || p_media_type || '/';
  if p_storage_object_name is null or length(p_storage_object_name)>1024
     or p_storage_object_name not like v_expected_prefix || '%'
     or p_storage_object_name like '%..%' or p_storage_object_name like '%\\%'
  then raise exception 'invalid_storage_object_name' using errcode='22023'; end if;

  if not exists (
    select 1 from storage.objects so
    where so.bucket_id='company-media' and so.name=p_storage_object_name
  ) then raise exception 'storage_object_not_found' using errcode='P0002'; end if;

  update public.company_media
     set status='archived', updated_at=now()
   where company_id=p_company_id and media_type=p_media_type
     and status='published' and storage_object_name<>p_storage_object_name;

  insert into public.company_media(
    company_id,storage_object_name,media_type,status,sort_order,alt_text,caption,updated_at
  ) values (
    p_company_id,p_storage_object_name,p_media_type,'published',p_sort_order,
    nullif(btrim(p_alt_text),''),nullif(btrim(p_caption),''),now()
  )
  on conflict (company_id,storage_object_name)
  do update set media_type=excluded.media_type,status='published',
    sort_order=excluded.sort_order,alt_text=excluded.alt_text,
    caption=excluded.caption,updated_at=now()
  returning * into v_media;

  return jsonb_build_object(
    'id',v_media.id,'company_id',v_media.company_id,
    'object_name',v_media.storage_object_name,'type',v_media.media_type,
    'status',v_media.status,'sort_order',v_media.sort_order,
    'alt',v_media.alt_text,'caption',v_media.caption,'updated_at',v_media.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_own_review_internal(p_submission_id uuid, p_actor_ref text, p_reason_code text, p_moderator_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_submission private.own_review_submissions%rowtype;
  v_review public.reviews%rowtype;
begin
  if p_actor_ref is null or char_length(btrim(p_actor_ref)) not between 3 and 120 then
    raise exception 'invalid actor reference';
  end if;

  if p_reason_code is null or char_length(btrim(p_reason_code)) not between 3 and 80
     or p_reason_code ~ '[^a-z0-9_]' then
    raise exception 'invalid reason code';
  end if;

  if p_moderator_note is not null and char_length(p_moderator_note) > 2000 then
    raise exception 'moderator note too long';
  end if;

  select s.* into v_submission
    from private.own_review_submissions s
   where s.id = p_submission_id
   for update;

  if not found then raise exception 'submission not found'; end if;

  if v_submission.status = 'removed' then
    return v_submission.published_review_id;
  end if;

  if v_submission.status <> 'published' or v_submission.published_review_id is null then
    raise exception 'only a published submission can be removed';
  end if;

  select r.* into v_review
    from public.reviews r
   where r.id = v_submission.published_review_id
     and r.company_id = v_submission.company_id
   for update;

  if not found then raise exception 'published review not found'; end if;

  update public.reviews
     set status = 'removed',
         source_updated_at = now(),
         updated_at = now()
   where id = v_review.id;

  update private.own_review_submissions
     set status = 'removed',
         moderator_notes = p_moderator_note,
         moderated_at = now(),
         updated_at = now()
   where id = v_submission.id;

  insert into public.audit_log (
    company_id, user_id, action, target_type, target_id, metadata
  )
  values (
    v_submission.company_id,
    null,
    'own_review.removed',
    'review',
    v_review.id::text,
    jsonb_build_object(
      'submission_id', v_submission.id,
      'previous_status', v_submission.status,
      'next_status', 'removed',
      'reason_code', btrim(p_reason_code),
      'actor_ref', btrim(p_actor_ref),
      'content_hash', v_review.content_hash
    )
  );

  return v_review.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_company_profile_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_company_id uuid; v_slug text; v_state text; v_headers jsonb; v_auth text;
begin
 if current_setting('otzovik.native_mirror',true)='on' then return coalesce(new,old); end if;
 if tg_table_name='source_ratings' then select rs.company_id into v_company_id from public.review_sources rs where rs.id=(case when tg_op='DELETE' then old.source_id else new.source_id end);
 elsif tg_table_name='companies' then v_company_id:=case when tg_op='DELETE' then old.id else new.id end;
 else v_company_id:=case when tg_op='DELETE' then old.company_id else new.company_id end; end if;
 if v_company_id is null then return coalesce(new,old); end if;
 select c.slug,coalesce(a.state,'disabled') into v_slug,v_state from public.companies c left join public.company_profile_public_access a on a.company_id=c.id where c.id=v_company_id and c.status='active';
 if v_slug is null or v_state<>'active' then return coalesce(new,old); end if;
 begin v_headers:=nullif(current_setting('request.headers',true),'')::jsonb; v_auth:=v_headers->>'authorization'; exception when others then v_auth:=null; end;
 if v_auth is null or v_auth not like 'Bearer %' then raise warning 'profile publish skipped: authenticated request context missing for %',v_slug; return coalesce(new,old); end if;
 perform net.http_post(url:='https://rzhlcszqtuhkhfibygnk.supabase.co/functions/v1/request-profile-publish',body:=jsonb_build_object('slug',v_slug),headers:=jsonb_build_object('Content-Type','application/json','Authorization',v_auth),timeout_milliseconds:=5000);
 return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION public.respond_to_my_company_review(p_company_id uuid, p_review_id uuid, p_statement text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid:=auth.uid(); v_role text; v_native jsonb; v_legacy uuid; v_external uuid; v_mirror boolean:=private.native_to_legacy_mirror_enabled_v1();
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select role into v_role from public.company_memberships where company_id=p_company_id and user_id=v_uid and verification_status='verified' and role in ('owner','admin','manager') limit 1;
 if v_role is null then raise exception 'company_write_access_required' using errcode='42501'; end if;
 v_native:=private.write_native_review_response_v1(p_company_id,p_review_id,p_statement,v_uid,v_role);
 if v_mirror then v_legacy:=private.mirror_native_review_response_to_legacy_v1(p_company_id,p_review_id,p_statement,v_uid); end if;
 v_external:=coalesce(v_legacy,(v_native->>'official_statement_id')::uuid);
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata) values(p_company_id,v_uid,'company_review.response_updated','review',p_review_id::text,jsonb_build_object('role',v_role,'statement_id',v_external,'legacy_statement_id',v_legacy,'native_statement_revision_id',v_native->>'statement_revision_id','write_model',case when v_mirror then 'native_first_legacy_mirror' else 'native_only' end));
 return jsonb_build_object('id',v_external,'review_id',p_review_id,'status','published','role',v_role);
end $function$

CREATE OR REPLACE FUNCTION public.revoke_company_access_invitation(p_invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid:=auth.uid(); v_company uuid;
begin
 if v_uid is null then raise exception using errcode='42501',message='Authentication required'; end if;
 select company_id into v_company from public.company_access_invitations where id=p_invitation_id and status='pending';
 if v_company is null then return false; end if;
 if not exists(select 1 from public.company_memberships where company_id=v_company and user_id=v_uid and role='owner' and verification_status='verified')
 then raise exception using errcode='42501',message='Verified owner required'; end if;
 update public.company_access_invitations set status='revoked',updated_at=now() where id=p_invitation_id and status='pending';
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.submit_own_review_internal(p_request_id uuid, p_company_slug text, p_location_id uuid, p_author_display_name text, p_author_email text, p_rating integer, p_body text, p_language text, p_terms_version text, p_privacy_version text, p_source_ip_hash text, p_user_agent text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_company_id uuid;
  v_submission_id uuid;
begin
  if p_company_slug is null
     or p_company_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
     or char_length(p_company_slug) > 63 then
    raise exception 'invalid company';
  end if;

  select c.id
    into v_company_id
    from public.companies c
    join public.company_profile_public_access a on a.company_id = c.id
   where c.slug = p_company_slug
     and c.status = 'active'
     and c.profile_status = 'ready'
     and a.state = 'active'
     and a.review_intake_enabled is true;

  if v_company_id is null then
    raise exception 'review intake unavailable';
  end if;

  if p_location_id is not null and not exists (
    select 1
      from public.company_locations l
     where l.id = p_location_id
       and l.company_id = v_company_id
       and l.status = 'published'
  ) then
    raise exception 'invalid location';
  end if;

  insert into private.own_review_submissions (
    request_id, company_id, location_id, author_display_name, author_email,
    rating, body, language, experience_confirmed_at, terms_accepted_at,
    terms_version, privacy_accepted_at, privacy_version, source_ip_hash,
    user_agent, status
  )
  values (
    p_request_id, v_company_id, p_location_id, btrim(p_author_display_name),
    lower(btrim(p_author_email)), p_rating, btrim(p_body),
    coalesce(nullif(p_language, ''), 'ru'), now(), now(), p_terms_version,
    now(), p_privacy_version, p_source_ip_hash, left(p_user_agent, 500), 'draft'
  )
  on conflict (request_id) do nothing
  returning id into v_submission_id;

  if v_submission_id is null then
    select s.id into v_submission_id
      from private.own_review_submissions s
     where s.request_id = p_request_id;
  end if;

  return v_submission_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_profile_slug_registry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_kind text := TG_ARGV[0];
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.slug IS NOT DISTINCT FROM OLD.slug THEN
    RETURN NEW;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    IF NEW.slug <> lower(btrim(NEW.slug))
       OR NEW.slug !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'
       OR NEW.slug IN ('www','api','admin','test','test2','account','login','profiles','specialists') THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid or reserved slug';
    END IF;
    INSERT INTO public.profile_slug_registry(slug,profile_kind,profile_id)
    VALUES (NEW.slug,v_kind,NEW.id);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    DELETE FROM public.profile_slug_registry
    WHERE slug=lower(btrim(OLD.slug)) AND profile_kind=v_kind AND profile_id=OLD.id;
  END IF;
  RETURN NULL; -- AFTER trigger return value is ignored
END
$function$

CREATE OR REPLACE FUNCTION public.unpublish_my_company_media(p_company_id uuid, p_storage_object_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_row public.company_media%rowtype;
begin
  if v_uid is null then
    raise exception 'unauthorized';
  end if;

  if not exists (
    select 1
    from public.company_memberships cm
    where cm.company_id = p_company_id
      and cm.user_id = v_uid
      and cm.verification_status = 'verified'
      and cm.role in ('owner','admin')
  ) then
    raise exception 'forbidden';
  end if;

  select * into v_row
  from public.company_media
  where company_id = p_company_id
    and storage_object_name = p_storage_object_name
  for update;

  if not found then
    raise exception 'media_not_found';
  end if;

  update public.company_media
  set status = 'archived',
      updated_at = now()
  where id = v_row.id;

  return jsonb_build_object(
    'id', v_row.id,
    'company_id', v_row.company_id,
    'object_name', v_row.storage_object_name,
    'type', v_row.media_type,
    'status', 'archived'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_company_profile(p_company_id uuid, p_name text, p_description text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_user_id uuid := auth.uid(); v_role text; v_old jsonb; v_new jsonb;
begin
 if v_user_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'name_required' using errcode='22023'; end if;
 if char_length(trim(p_name))>200 then raise exception 'name_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_description,''))>2000 then raise exception 'description_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_website,''))>500 then raise exception 'website_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_phone,''))>100 then raise exception 'phone_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_city,''))>120 then raise exception 'city_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_email,''))>320 then raise exception 'email_too_long' using errcode='22023'; end if;
 select cm.role into v_role from public.company_memberships cm join public.companies c on c.id=cm.company_id and c.status='active'
 where cm.user_id=v_user_id and cm.company_id=p_company_id and cm.verification_status='verified' and cm.role in ('owner','admin') limit 1;
 if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;
 select jsonb_build_object('name',c.name,'description',c.description,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email)
 into v_old from public.companies c where c.id=p_company_id for update;
 update public.companies set name=trim(p_name),description=nullif(trim(coalesce(p_description,'')),''),
 website=nullif(trim(coalesce(p_website,'')),''),phone=nullif(trim(coalesce(p_phone,'')),''),
 city=nullif(trim(coalesce(p_city,'')),''),email=nullif(trim(coalesce(p_email,'')),''),
 updated_at=now() where id=p_company_id;
 select jsonb_build_object('id',c.id,'slug',c.slug,'name',c.name,'description',c.description,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email,'status',c.status,'profile_status',c.profile_status)
 into v_new from public.companies c where c.id=p_company_id;
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
 values(p_company_id,v_user_id,'company_profile.updated','company',p_company_id::text,jsonb_build_object('role',v_role,'before',v_old,'after',v_new));
 return jsonb_build_object('company_id',p_company_id,'role',v_role,'company',v_new);
end; $function$

CREATE OR REPLACE FUNCTION public.update_my_company_profile(p_company_id uuid, p_name text, p_website text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid(); v_role text; v_old jsonb; v_new jsonb;
begin
  if v_user_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'name_required' using errcode='22023'; end if;
  select cm.role into v_role from public.company_memberships cm join public.companies c on c.id=cm.company_id and c.status='active'
  where cm.user_id=v_user_id and cm.company_id=p_company_id and cm.verification_status='verified' and cm.role in ('owner','admin') limit 1;
  if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;
  select jsonb_build_object('name',c.name,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email) into v_old from public.companies c where c.id=p_company_id for update;
  update public.companies set name=trim(p_name),website=nullif(trim(coalesce(p_website,'')),''),phone=nullif(trim(coalesce(p_phone,'')),''),city=nullif(trim(coalesce(p_city,'')),''),email=nullif(trim(coalesce(p_email,'')),''),updated_at=now() where id=p_company_id;
  select jsonb_build_object('name',c.name,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email) into v_new from public.companies c where c.id=p_company_id;
  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata) values(p_company_id,v_user_id,'company_profile.updated','company',p_company_id::text,jsonb_build_object('role',v_role,'before',v_old,'after',v_new));
  return jsonb_build_object('company_id',p_company_id,'role',v_role,'company',v_new);
end; $function$

CREATE OR REPLACE FUNCTION public.update_my_specialist_draft(p_id uuid, p_display_name text, p_profession text, p_specialization text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid(); v_id uuid;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authentication required'; END IF;
 IF char_length(btrim(coalesce(p_display_name,''))) NOT BETWEEN 2 AND 150 OR char_length(btrim(coalesce(p_profession,''))) NOT BETWEEN 1 AND 120 OR char_length(coalesce(p_specialization,'')) > 160 OR char_length(coalesce(p_city,'')) > 120 OR char_length(coalesce(p_description,'')) > 2000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid fields'; END IF;
 UPDATE public.specialist_profiles SET display_name=btrim(p_display_name),profession=nullif(btrim(coalesce(p_profession,'')),''),specialization=nullif(btrim(coalesce(p_specialization,'')),''),city=nullif(btrim(coalesce(p_city,'')),''),description=nullif(btrim(coalesce(p_description,'')),''),updated_at=now() WHERE id=p_id AND owner_user_id=v_uid AND profile_status='draft' RETURNING id INTO v_id;
 IF v_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft not found or access denied'; END IF;
 RETURN jsonb_build_object('id',v_id,'profile_status','draft');
END
$function$

CREATE OR REPLACE FUNCTION public.upsert_my_company_knowledge(p_company_id uuid, p_concept_id uuid, p_concept_type text, p_scope_type text, p_branch_id uuid, p_service_id uuid, p_language text, p_title text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare v_uid uuid:=auth.uid(); v_role text; v_concept uuid:=p_concept_id; v_ver uuid; v_variant uuid; v_n int;
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select cm.role into v_role from public.company_memberships cm join public.role_permissions rp on rp.role=cm.role and rp.permission_code='knowledge.create'
 where cm.company_id=p_company_id and cm.user_id=v_uid and cm.verification_status='verified' limit 1;
 if v_role is null then raise exception 'knowledge_create_access_required' using errcode='42501'; end if;
 if length(btrim(coalesce(p_body,'')))<1 then raise exception 'invalid_body' using errcode='22023'; end if;
 if p_scope_type not in ('company','branch','service') then raise exception 'invalid_scope' using errcode='22023'; end if;
 if (p_scope_type='company' and (p_branch_id is not null or p_service_id is not null))
 or (p_scope_type='branch' and (p_branch_id is null or p_service_id is not null))
 or (p_scope_type='service' and (p_service_id is null or p_branch_id is not null)) then raise exception 'invalid_scope_target' using errcode='22023'; end if;

 if v_concept is null then
   insert into private.knowledge_concepts_v1(company_id,concept_type,scope_type,branch_id,service_id,authority,status)
   values(p_company_id,coalesce(nullif(btrim(p_concept_type),''),'faq'),p_scope_type,p_branch_id,p_service_id,'native','active')
   returning id into v_concept;
 else
   perform 1 from private.knowledge_concepts_v1 where id=v_concept and company_id=p_company_id and authority='native';
   if not found then raise exception 'knowledge_concept_not_found' using errcode='P0002'; end if;
 end if;

 select coalesce(max(version),0)+1 into v_n from private.knowledge_versions_v1 where company_id=p_company_id and concept_id=v_concept;
 update private.knowledge_versions_v1 set status='superseded' where company_id=p_company_id and concept_id=v_concept and status='current';
 insert into private.knowledge_versions_v1(company_id,concept_id,version,source_language,source_title,source_body,content_checksum,status,provenance)
 values(p_company_id,v_concept,v_n,coalesce(nullif(btrim(p_language),''),'ru'),nullif(btrim(p_title),''),btrim(p_body),
 encode(extensions.digest(btrim(p_body),'sha256'),'hex'),'current',jsonb_build_object('source','cabinet','actor_user_id',v_uid::text,'actor_role',v_role))
 returning id into v_ver;
 insert into private.knowledge_variants_v1(company_id,version_id,language,title,body,origin,source_checksum,verification_status,provenance)
 values(p_company_id,v_ver,coalesce(nullif(btrim(p_language),''),'ru'),nullif(btrim(p_title),''),btrim(p_body),'human',
 encode(extensions.digest(btrim(p_body),'sha256'),'hex'),'unverified',jsonb_build_object('source','cabinet','actor_user_id',v_uid::text))
 returning id into v_variant;
 return jsonb_build_object('concept_id',v_concept,'version_id',v_ver,'variant_id',v_variant,'verification_status','unverified','published',false);
end $function$

CREATE OR REPLACE FUNCTION public.upsert_my_company_question_answer(p_company_id uuid, p_id uuid, p_question text, p_answer text, p_category text DEFAULT NULL::text, p_program_label text DEFAULT NULL::text, p_publish boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid:=auth.uid(); v_role text; v_qid uuid; v_native jsonb; v_legacy uuid; v_external uuid; v_mirror boolean:=private.native_to_legacy_mirror_enabled_v1(); v_status text:=case when p_publish then 'published' else 'draft' end;
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select role into v_role from public.company_memberships where company_id=p_company_id and user_id=v_uid and verification_status='verified' and role in ('owner','admin','manager') limit 1;
 if v_role is null then raise exception 'company_write_access_required' using errcode='42501'; end if;
 if p_id is not null then select q.id into v_qid from private.questions_v1 q where q.company_id=p_company_id and (q.id=p_id or q.legacy_qna_id=p_id) limit 1; if v_qid is null then raise exception 'question_answer_not_found' using errcode='P0002'; end if; end if;
 v_native:=private.write_native_qna_v1(p_company_id,v_qid,p_question,p_answer,p_category,p_program_label,p_publish,v_uid,v_role); v_qid:=(v_native->>'question_id')::uuid;
 if v_mirror then v_legacy:=private.mirror_native_qna_to_legacy_v1(p_company_id,v_qid,p_question,p_answer,p_category,p_program_label,p_publish,v_uid,v_role); end if;
 v_external:=coalesce(v_legacy,v_qid);
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata) values(p_company_id,v_uid,'company_question_answer.upserted','question_answer',v_external::text,jsonb_build_object('role',v_role,'status',v_status,'question_id',v_qid,'legacy_id',v_legacy,'write_model',case when v_mirror then 'native_first_legacy_mirror' else 'native_only' end));
 return jsonb_build_object('id',v_external,'status',v_status,'role',v_role);
end $function$

CREATE OR REPLACE FUNCTION public.validate_company_statement_review_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.reviews r
    where r.id = new.review_id::uuid
      and r.company_id = new.company_id
      and r.status = 'published'
  ) then
    raise exception 'review unavailable or belongs to another company' using errcode='23503';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_my_company_knowledge(p_company_id uuid, p_variant_id uuid, p_decision text, p_review_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare v_uid uuid:=auth.uid(); v_role text; v_status text; v_actor uuid;
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select cm.role into v_role from public.company_memberships cm join public.role_permissions rp on rp.role=cm.role and rp.permission_code='knowledge.publish'
 where cm.company_id=p_company_id and cm.user_id=v_uid and cm.verification_status='verified' limit 1;
 if v_role is null then raise exception 'knowledge_verify_access_required' using errcode='42501'; end if;
 v_status:=case p_decision when 'verify' then 'verified' when 'reject' then 'rejected' else null end;
 if v_status is null then raise exception 'invalid_decision' using errcode='22023'; end if;
 if v_status='verified' then
   v_actor:=private.resolve_human_actor_v1(v_uid);
   if v_actor is null then raise exception 'human_actor_required_for_verification' using errcode='42501'; end if;
 end if;
 update private.knowledge_variants_v1 set verification_status=v_status,
 verified_by_actor_id=case when v_status='verified' then v_actor else null end,
 verified_at=case when v_status='verified' then now() else null end,
 review_due_at=case when v_status='verified' then p_review_due_at else null end,updated_at=now()
 where id=p_variant_id and company_id=p_company_id;
 if not found then raise exception 'knowledge_variant_not_found' using errcode='P0002'; end if;
 return jsonb_build_object('variant_id',p_variant_id,'verification_status',v_status);
end $function$

CREATE OR REPLACE FUNCTION public.verify_ownership_claim(p_claim_id uuid, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'private'
AS $function$
declare
  v_claim public.ownership_claims%rowtype;
  v_operator boolean;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_decision not in ('approve','reject') then raise exception 'invalid decision' using errcode='22023'; end if;

  select exists (
    select 1 from private.moderation_operators mo
    where mo.user_id=auth.uid() and mo.active
  ) into v_operator;
  if not v_operator then raise exception 'moderation access required' using errcode='42501'; end if;

  select * into v_claim from public.ownership_claims where id=p_claim_id for update;
  if not found then raise exception 'claim not found' using errcode='P0002'; end if;
  if v_claim.status <> 'pending' then raise exception 'claim is not pending' using errcode='P0001'; end if;

  if p_decision='approve' then
    insert into public.company_memberships(company_id,user_id,role,verification_status)
    values(v_claim.company_id,v_claim.user_id,v_claim.role_claimed,'verified')
    on conflict (company_id,user_id) do update set role=excluded.role, verification_status='verified';

    update public.ownership_claims
      set status='approved', review_note=nullif(trim(coalesce(p_review_note,''),''), ''), verified_at=now(), updated_at=now()
      where id=v_claim.id;

    insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
    values(v_claim.company_id,auth.uid(),'ownership_claim.approved','ownership_claim',v_claim.id,jsonb_build_object('claim_user_id',v_claim.user_id,'role',v_claim.role_claimed));
  else
    update public.ownership_claims
      set status='rejected', review_note=nullif(trim(coalesce(p_review_note,''),''), ''), updated_at=now()
      where id=v_claim.id;

    insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
    values(v_claim.company_id,auth.uid(),'ownership_claim.rejected','ownership_claim',v_claim.id,jsonb_build_object('claim_user_id',v_claim.user_id));
  end if;

  select jsonb_build_object('claim_id',id,'status',status,'company_id',company_id,'user_id',user_id,'role_claimed',role_claimed,'verified_at',verified_at)
    into v_result from public.ownership_claims where id=v_claim.id;
  return v_result;
end;
$function$
